def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i

def valid(s):
    pairs, st = {")": "(", "]": "[", "}": "{"}, []
    for ch in s:
        if ch in "([{":
            st.append(ch)
        elif ch in pairs:
            if not st or st.pop() != pairs[ch]:
                return False
    return not st

def is_pal(s):
    t = [c.lower() for c in s if c.isalnum()]
    return t == t[::-1]

def second(nums):
    a = b = float("-inf")
    for x in nums:
        if x > a:
            a, b = x, a
        elif a > x > b:
            b = x
    return None if b == float("-inf") else b

