def max_profit(prices):
    low, best = float("inf"), 0
    for p in prices:
        low = min(low, p)
        best = max(best, p - low)
    return best

def ffill(a):
    last = 0
    for i, x in enumerate(a):
        if x is None:
            a[i] = last
        else:
            last = x
    return a

def longest_run(s):
    best_ch, best, cur, prev = None, 0, 0, None
    for ch in s:
        cur = cur + 1 if ch == prev else 1
        prev = ch
        if cur > best:
            best, best_ch = cur, ch
    return best_ch, best

