def longest(s):
    seen, left, best = {}, 0, 0
    for i, ch in enumerate(s):
        if seen.get(ch, -1) >= left:
            left = seen[ch] + 1
        seen[ch] = i
        best = max(best, i - left + 1)
    return best

import time, functools
def retry(n=3, base=1):
    def deco(f):
        @functools.wraps(f)
        def wrap(*a, **kw):
            for i in range(n):
                try:
                    return f(*a, **kw)
                except Exception:
                    if i == n - 1:
                        raise
                    time.sleep(base * 2 ** i)
        return wrap
    return deco

from collections import OrderedDict
class LRU:
    def __init__(self, cap):
        self.cap, self.d = cap, OrderedDict()
    def get(self, k):
        if k not in self.d:
            return -1
        self.d.move_to_end(k)
        return self.d[k]
    def put(self, k, v):
        self.d[k] = v
        self.d.move_to_end(k)
        if len(self.d) > self.cap:
            self.d.popitem(last=False)

