import random
def reservoir(stream):
    pick = None
    for i, x in enumerate(stream, 1):
        if random.randrange(i) == 0:
            pick = x
    return pick

def primes(n):
    is_p = [True] * (n + 1)
    is_p[:2] = [False, False]
    for i in range(2, int(n ** 0.5) + 1):
        if is_p[i]:
            is_p[i*i::i] = [False] * len(range(i*i, n + 1, i))
    return [i for i, p in enumerate(is_p) if p]

