from collections import Counter
pat = re.compile(r'^(\S+) .*?" (\d{3}) ')
def errors(lines):
    c = Counter()
    for line in lines:
        m = pat.match(line)
        if m and m.group(2).startswith("5"):
            c[m.group(1)] += 1
    return c

